from math import comb

def binomial(k, n, p):
    return comb(n, k) * p ** k * (1 - p) ** (n - k)
print(round(binomial(3, 10, 0.3), 3), round(binomial(0, 10, 0.3), 3))   # 0.267 0.028

def uniform_density(x):
    return 1.0 if 0 <= x <= 1 else 0.0

print(uniform_density(0.2), uniform_density(0.9), uniform_density(1.5))   # 1.0 1.0 0.0

from math import exp, pi, sqrt

def gaussian(x, mu=0.0, sigma=1.0):
    return exp(-((x - mu) ** 2) / (2 * sigma ** 2)) / (sigma * sqrt(2 * pi))
from math import erf

print(round(gaussian(0), 3), round(gaussian(1), 3))   # 0.399 0.242
print(round(erf(1 / sqrt(2)), 3))                    # 0.683: share within one sigma

